SELECT

FROM alert_notification
WHERE rule_id = #{ruleId}
AND created_at >= #{since}
ORDER BY id DESC

SELECT

FROM alert_notification

    AND level = #{level}
    AND read_flag = 0

ORDER BY FIELD(level, 'critical', 'warn', 'info'), created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}
